$page_title='เอกสารคำสั่งซื้อ';$noindex=true;require_once __DIR__.'/includes/auth_check.php';requireLogin();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$id=(int)($_GET['id']??0);
$sql='SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=?'.(isAdmin()?'':' AND o.user_id=?');$s=$db->prepare($sql);$params=[$id];if(!isAdmin())$params[]=(int)$_SESSION['user_id'];$s->execute($params);$order=$s->fetch();if(!$order){http_response_code(404);exit('ไม่พบเอกสาร');}$s=$db->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();require __DIR__.'/includes/header.php';
?><div class="container print-document" style="max-width:850px;padding:38px 16px 70px"><div style="display:flex;justify-content:space-between;gap:20px"><div><h1><?php echo $order['payment_status']==='paid'?'ใบยืนยันการชำระเงิน':'ใบยืนยันคำสั่งซื้อ';?></h1><p>KitchenMart · เอกสารอิเล็กทรอนิกส์สำหรับอ้างอิง ไม่ใช่ใบกำกับภาษี</p></div><button class="btn btn-primary no-print" onclick="window.print()"><i class="fa-solid fa-print"></i> พิมพ์ / บันทึก PDF</button></div><hr><p><strong>เลขคำสั่งซื้อ:</strong> <?php echo e($order['order_no']);?><br><strong>วันที่:</strong> <?php echo date('d/m/Y H:i',strtotime($order['created_at']));?><br><strong>สถานะชำระเงิน:</strong> <?php echo e($order['payment_status']);?></p><h3>ผู้รับสินค้า</h3><p><?php echo e($order['shipping_name']);?> · <?php echo e($order['shipping_phone']);?><br><?php echo nl2br(e($order['shipping_address']));?></p><table style="width:100%;border-collapse:collapse"><thead><tr><th align="left">สินค้า</th><th>จำนวน</th><th align="right">ยอดรวม</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?php echo e($item['product_name']);?></td><td align="center"><?php echo (int)$item['quantity'];?></td><td align="right"><?php echo formatCurrency($item['subtotal']);?></td></tr><?php endforeach;?></tbody></table><hr><p style="text-align:right;font-size:1.3rem"><strong>ยอดสุทธิ <?php echo formatCurrency($order['total_amount']);?></strong></p></div><style>.print-document th,.print-document td{padding:12px;border-bottom:1px solid #ddd}@media print{header,footer,.mobile-bottom-nav,.announcement,.no-print{display:none!important}.print-document{max-width:none!important;padding:0!important}}</style><?php require __DIR__.'/includes/footer.php';?>
